CREATE TABLE of_shops (id TEXT PRIMARY KEY, owner TEXT NOT NULL UNIQUE, name TEXT NOT NULL DEFAULT '', settings TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE of_forms (id INTEGER PRIMARY KEY AUTOINCREMENT, shop TEXT NOT NULL REFERENCES of_shops(id), token TEXT NOT NULL UNIQUE, data TEXT NOT NULL CHECK(json_valid(data)), revision INTEGER NOT NULL DEFAULT 1, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX of_forms_shop ON of_forms(shop,active,id);
CREATE TABLE of_items (id INTEGER PRIMARY KEY AUTOINCREMENT, shop TEXT NOT NULL REFERENCES of_shops(id), form_id INTEGER NOT NULL REFERENCES of_forms(id), data TEXT NOT NULL CHECK(json_valid(data)), price INTEGER NOT NULL CHECK(price>=0), stock INTEGER NOT NULL DEFAULT 999999 CHECK(stock>=0), active INTEGER NOT NULL DEFAULT 1, revision INTEGER NOT NULL DEFAULT 1);
CREATE INDEX of_items_form ON of_items(shop,form_id,active,id);
CREATE TABLE of_customers (id INTEGER PRIMARY KEY AUTOINCREMENT, shop TEXT NOT NULL REFERENCES of_shops(id), mobile TEXT NOT NULL, name TEXT NOT NULL, data TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, UNIQUE(shop,mobile));
CREATE TABLE of_orders (id INTEGER PRIMARY KEY AUTOINCREMENT, shop TEXT NOT NULL REFERENCES of_shops(id), form_id INTEGER NOT NULL REFERENCES of_forms(id), customer_id INTEGER NOT NULL REFERENCES of_customers(id), key TEXT NOT NULL UNIQUE, idempotency TEXT NOT NULL, request_hash TEXT NOT NULL, order_date TEXT NOT NULL, status TEXT NOT NULL DEFAULT '00' CHECK(status IN ('00','10','22','24','30','40')), ispaid TEXT NOT NULL DEFAULT 'N' CHECK(ispaid IN ('Y','N')), amount INTEGER NOT NULL CHECK(amount>=0), fee INTEGER NOT NULL CHECK(fee>=0), data TEXT NOT NULL CHECK(json_valid(data)), merged_into INTEGER REFERENCES of_orders(id), revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(form_id,idempotency));
CREATE INDEX of_orders_shop_date ON of_orders(shop,order_date DESC,id DESC);
CREATE INDEX of_orders_customer ON of_orders(shop,customer_id,created_at);
CREATE TABLE of_order_items (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL REFERENCES of_orders(id), item_id INTEGER NOT NULL REFERENCES of_items(id), name TEXT NOT NULL, unit TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 9999), price INTEGER NOT NULL CHECK(price>=0), UNIQUE(order_id,item_id));
CREATE TRIGGER of_stock_reserve AFTER INSERT ON of_order_items BEGIN UPDATE of_items SET stock=stock-NEW.quantity,revision=revision+1 WHERE id=NEW.item_id; END;
CREATE TRIGGER of_stock_item_delete AFTER DELETE ON of_order_items WHEN (SELECT status FROM of_orders WHERE id=OLD.order_id)<>'40' BEGIN UPDATE of_items SET stock=stock+OLD.quantity,revision=revision+1 WHERE id=OLD.item_id; END;
CREATE TRIGGER of_stock_item_edit AFTER UPDATE OF quantity ON of_order_items BEGIN UPDATE of_items SET stock=stock+OLD.quantity-NEW.quantity,revision=revision+1 WHERE id=NEW.item_id; END;
CREATE TRIGGER of_stock_cancel AFTER UPDATE OF status ON of_orders WHEN NEW.status='40' AND OLD.status<>'40' BEGIN UPDATE of_items SET stock=stock+COALESCE((SELECT quantity FROM of_order_items WHERE order_id=NEW.id AND item_id=of_items.id),0) WHERE id IN (SELECT item_id FROM of_order_items WHERE order_id=NEW.id); END;
CREATE TRIGGER of_no_uncancel BEFORE UPDATE OF status ON of_orders WHEN OLD.status='40' AND NEW.status<>'40' BEGIN SELECT RAISE(ABORT,'cancelled_order_is_final'); END;
CREATE TRIGGER of_no_reopen_completed BEFORE UPDATE OF status ON of_orders WHEN OLD.status='30' AND NEW.status<>'30' BEGIN SELECT RAISE(ABORT,'completed_order_is_final'); END;
CREATE TABLE of_ledger (id INTEGER PRIMARY KEY AUTOINCREMENT, shop TEXT NOT NULL REFERENCES of_shops(id), mobile TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('point','prepay')), delta INTEGER NOT NULL CHECK(delta<>0), memo TEXT NOT NULL, operation TEXT NOT NULL, actor TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(shop,operation));
CREATE INDEX of_ledger_balance ON of_ledger(shop,mobile,kind,id);
CREATE TRIGGER of_nonnegative_balance AFTER INSERT ON of_ledger WHEN (SELECT SUM(delta) FROM of_ledger WHERE shop=NEW.shop AND mobile=NEW.mobile AND kind=NEW.kind)<0 BEGIN SELECT RAISE(ABORT,'insufficient_balance'); END;
CREATE TABLE of_records (id INTEGER PRIMARY KEY AUTOINCREMENT, shop TEXT NOT NULL REFERENCES of_shops(id), kind TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), revision INTEGER NOT NULL DEFAULT 1, deleted INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX of_records_kind ON of_records(shop,kind,deleted,id);
CREATE TABLE of_changes (id INTEGER PRIMARY KEY AUTOINCREMENT, shop TEXT NOT NULL, kind TEXT NOT NULL, entity TEXT NOT NULL, actor TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX of_changes_shop ON of_changes(shop,id);
CREATE TABLE of_staff (id INTEGER PRIMARY KEY AUTOINCREMENT, shop TEXT NOT NULL REFERENCES of_shops(id), login TEXT NOT NULL UNIQUE, name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'STAFF', permissions TEXT NOT NULL DEFAULT '{}', active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE of_sessions (hash TEXT PRIMARY KEY, staff_id INTEGER NOT NULL REFERENCES of_staff(id), expires_at TEXT NOT NULL);
CREATE TABLE of_submissions (fingerprint TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX of_submission_gate ON of_submissions(fingerprint,created_at);
CREATE TABLE of_guards (id TEXT PRIMARY KEY, ok INTEGER NOT NULL CHECK(ok=1));
